'use strict';

// MODULES //

var resolve = require( 'path' ).resolve;
var tape = require( 'tape' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var isPositiveZero = require( '@stdlib/math/base/assert/is-positive-zero' );
var isNegativeZero = require( '@stdlib/math/base/assert/is-negative-zero' );
var PINF = require( '@stdlib/constants/float64/pinf' );
var NINF = require( '@stdlib/constants/float64/ninf' );
var EPS = require( '@stdlib/constants/float64/eps' );
var abs = require( '@stdlib/math/base/special/abs' );
var tryRequire = require( '@stdlib/utils/try-require' );


// VARIABLES //

var roundsdf = tryRequire( resolve( __dirname, './../lib/native.js' ) );
var opts = {
	'skip': ( roundsdf instanceof Error )
};


// TESTS //

tape( 'main export is a function', opts, function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof roundsdf, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function returns `NaN` if provided `NaN`', opts, function test( t ) {
	var v;

	v = roundsdf( NaN, 2, 10 );
	t.strictEqual( isnan( v ), true, 'returns NaN' );

	t.end();
});

tape( 'the function returns `NaN` if provided `n < 1`', opts, function test( t ) {
	var v;

	v = roundsdf( 3.14, 0, 10 );
	t.strictEqual( isnan( v ), true, 'returns NaN' );

	v = roundsdf( 3.14, -1, 10 );
	t.strictEqual( isnan( v ), true, 'returns NaN' );

	t.end();
});

tape( 'the function returns `NaN` if provided a base less than 1', opts, function test( t ) {
	var v;

	v = roundsdf( 3.14, 2, 0 );
	t.strictEqual( isnan( v ), true, 'returns NaN' );

	v = roundsdf( 3.14, 2, -1 );
	t.strictEqual( isnan( v ), true, 'returns NaN' );

	t.end();
});

tape( 'the function returns `+infinity` if provided `+infinity`', opts, function test( t ) {
	var v = roundsdf( PINF, 3, 10 );
	t.strictEqual( v, PINF, 'returns +infinity' );
	t.end();
});

tape( 'the function returns `-infinity` if provided `-infinity`', opts, function test( t ) {
	var v = roundsdf( NINF, 3, 10 );
	t.strictEqual( v, NINF, 'returns -infinity' );
	t.end();
});

tape( 'the function returns `+0` if provided `+0`', opts, function test( t ) {
	var v = roundsdf( 0.0, 2, 10 );
	t.strictEqual( isPositiveZero( v ), true, 'returns +0' );
	t.end();
});

tape( 'the function returns `-0` if provided `-0`', opts, function test( t ) {
	var v = roundsdf( -0.0, 2, 10 );
	t.strictEqual( isNegativeZero( v ), true, 'returns -0' );
	t.end();
});

tape( 'the function supports rounding a numeric value with a specified number of significant figures', opts, function test( t ) {
	t.strictEqual( roundsdf( 3.141592653589793, 1, 10 ), 4.0, 'returns expected value' );
	t.strictEqual( roundsdf( 3.141592653589793, 2, 10 ), 3.2, 'returns expected value' );
	t.strictEqual( roundsdf( 3.141592653589793, 3, 10 ), 3.15, 'returns expected value' );
	t.strictEqual( roundsdf( 3.141592653589793, 4, 10 ), 3.142, 'returns expected value' );
	t.strictEqual( roundsdf( 3.141592653589793, 5, 10 ), 3.1416, 'returns expected value' );
	t.end();
});

tape( 'the function supports rounding large positive values', opts, function test( t ) {
	t.strictEqual( roundsdf( 12368.0, 1, 10 ), 20000.0, 'returns expected value' );
	t.strictEqual( roundsdf( 12368.0, 2, 10 ), 13000.0, 'returns expected value' );
	t.strictEqual( roundsdf( 12368.0, 3, 10 ), 12400.0, 'returns expected value' );
	t.end();
});

tape( 'the function supports rounding negative values', opts, function test( t ) {
	t.strictEqual( roundsdf( -3.141592653589793, 1, 10 ), -3.0, 'returns expected value' );
	t.strictEqual( roundsdf( -3.141592653589793, 3, 10 ), -3.14, 'returns expected value' );
	t.strictEqual( roundsdf( -12368.0, 2, 10 ), -12000.0, 'returns expected value' );
	t.end();
});

tape( 'the function supports rounding using a custom base', opts, function test( t ) {
	var expected;
	var delta;
	var tol;
	var v;

	v = roundsdf( 0.0313, 2, 2 );
	expected = 0.03125;

	if ( v === expected ) {
		t.strictEqual( v, expected, 'returns expected value' );
	} else {
		delta = abs( v - expected );
		tol = 1.0 * EPS * abs( expected );
		t.ok( delta <= tol, 'within tolerance. v: '+v+'. expected: '+expected+'. delta: '+delta+'. tol: '+tol+'.' );
	}

	t.end();
});

tape( 'the function rounds toward positive infinity', opts, function test( t ) {
	t.strictEqual( roundsdf( 3.14, 1, 10 ), 4.0, 'returns expected value' );
	t.strictEqual( roundsdf( -3.14, 1, 10 ), -3.0, 'returns expected value' );
	t.strictEqual( roundsdf( 9.5, 1, 10 ), 10.0, 'returns expected value' );
	t.strictEqual( roundsdf( 9.4, 1, 10 ), 10.0, 'returns expected value' );
	t.strictEqual( roundsdf( 0.0, 2, 10 ), 0.0, 'returns expected value' );
	t.strictEqual( roundsdf( -0.0, 2, 10 ), -0.0, 'returns expected value' );
	t.end();
});

tape( 'the function supports small positive values', opts, function test( t ) {
	var v;

	v = roundsdf( 0.00123, 2, 10 );
	t.strictEqual( v, 0.0013, 'returns expected value' );

	v = roundsdf( 0.00567, 1, 10 );
	t.strictEqual( v, 0.006, 'returns expected value' );

	t.end();
});

tape( 'the function supports small negative values', opts, function test( t ) {
	var v;

	v = roundsdf( -0.00123, 2, 10 );
	t.strictEqual( v, -0.0012, 'returns expected value' );

	v = roundsdf( -0.00567, 1, 10 );
	t.strictEqual( v, -0.005, 'returns expected value' );

	t.end();
});

tape( 'the function handles very large numbers', opts, function test( t ) {
	var v;

	v = roundsdf( 1.23456789e15, 3, 10 );
	t.strictEqual( v, 1.24e15, 'returns expected value' );

	v = roundsdf( -9.87654321e14, 2, 10 );
	t.strictEqual( v, -9.8e14, 'returns expected value' );

	t.end();
});

tape( 'the function handles different bases correctly', opts, function test( t ) {
	var v;

	// Binary (base 2)
	v = roundsdf( 7.5, 3, 2 );
	t.ok( v >= 7.5, 'rounds toward positive infinity in base 2' );

	// Hexadecimal (base 16)
	v = roundsdf( 255.5, 2, 16 );
	t.ok( v >= 255.5, 'rounds toward positive infinity in base 16' );

	t.end();
});
